steps.sampleSolution:
#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> valores = {40, 10, 30};
    if (!valores.empty()) {
        std::sort(valores.begin(), valores.end());
        std::cout << std::max(valores[0], valores[2]) << "\n";
    }
    return 0;
}
